    // Security and Utility Functions
    function sanitizeInput(input) {
      if (typeof input !== 'string') return '';

      // Create a temporary div to safely escape HTML
      const div = document.createElement('div');
      div.textContent = input;
      let escaped = div.innerHTML;

      // Remove any remaining script tags and event handlers
      escaped = escaped.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
        .replace(/javascript:/gi, '')
        .replace(/on\w+\s*=/gi, '')
        .replace(/<iframe[^>]*>/gi, '')
        .replace(/<object[^>]*>/gi, '')
        .replace(/<embed[^>]*>/gi, '')
        .replace(/data:[^;]*;base64[^"']*/gi, '');

      return escaped.trim();
    }

    function safeJSONParse(jsonString, fallback = null) {
      try {
        if (typeof jsonString !== 'string') return fallback;
        const parsed = JSON.parse(jsonString);
        return validateSaveData(parsed) ? parsed : fallback;
      } catch (error) {
        logError('JSON Parse Error', error);
        return fallback;
      }
    }

    function validateSaveData(data) {
      if (!data || typeof data !== 'object') return false;

      const requiredFields = ['points', 'runEarned', 'lifetimeEarned', 'totalClicks', 'current', 'unlocked'];
      for (const field of requiredFields) {
        if (!(field in data)) return false;
      }

      if (typeof data.points !== 'number' || data.points < 0) return false;
      if (typeof data.runEarned !== 'number' || data.runEarned < 0) return false;
      if (typeof data.lifetimeEarned !== 'number' || data.lifetimeEarned < 0) return false;
      if (typeof data.totalClicks !== 'number' || data.totalClicks < 0) return false;
      if (typeof data.current !== 'string') return false;
      if (!Array.isArray(data.unlocked)) return false;

      return true;
    }

    function safeGetElementById(id) {
      try {
        const element = document.getElementById(id);
        return element || null;
      } catch (error) {
        logError('DOM Element Access Error', error);
        return null;
      }
    }

    function logError(message, error) {
      console.error(`[Brainrot Clicker Error] ${message}:`, error);

      // Categorize errors for user notifications
      const errorCategory = categorizeError(message, error);

      // Show user-friendly notification for critical errors
      if (errorCategory.critical) {
        showUserErrorNotification(errorCategory.userMessage, errorCategory.action);
      }

      // Store error log for debugging (limited to prevent memory issues)
      if (!G.errorLog) G.errorLog = [];
      G.errorLog.push({
        timestamp: Date.now(),
        message: message,
        error: error.toString(),
        category: errorCategory.type,
        critical: errorCategory.critical
      });

      // Keep only last 50 errors to prevent memory issues
      if (G.errorLog.length > 50) {
        G.errorLog = G.errorLog.slice(-50);
      }

      // Could send to analytics service in production
    }

    function logSuccess(message, data = null) {
      console.log(`[Brainrot Clicker Success] ${message}`, data || '');

      // Store success log for debugging (limited to prevent memory issues)
      if (!G.successLog) G.successLog = [];
      G.successLog.push({
        timestamp: Date.now(),
        message: message,
        data: data
      });

      // Keep only last 20 success messages to prevent memory issues
      if (G.successLog.length > 20) {
        G.successLog = G.successLog.slice(-20);
      }
    }

    function categorizeError(message, error) {
      const errorMsg = error.toString().toLowerCase();
      const messageLower = message.toLowerCase();

      // Storage errors
      if (messageLower.includes('storage') || errorMsg.includes('quota') || errorMsg.includes('storage')) {
        return {
          type: 'storage',
          critical: true,
          userMessage: '💾 Save failed! Your browser storage might be full. Try clearing some data or use a save code.',
          action: 'save'
        };
      }

      // Network errors
      if (errorMsg.includes('network') || errorMsg.includes('fetch')) {
        return {
          type: 'network',
          critical: false,
          userMessage: '🌐 Network issue detected. Some features may not work properly.',
          action: 'none'
        };
      }

      // Save/Load errors
      if (messageLower.includes('save') || messageLower.includes('load')) {
        return {
          type: 'save_load',
          critical: true,
          userMessage: '⚠️ Save/Load error! Your progress might not be saved properly.',
          action: 'save'
        };
      }

      // Calculation errors
      if (messageLower.includes('calculation') || errorMsg.includes('math')) {
        return {
          type: 'calculation',
          critical: false,
          userMessage: '🧮 Calculation error detected. Game balance might be affected.',
          action: 'none'
        };
      }

      // DOM errors
      if (messageLower.includes('dom') || errorMsg.includes('element')) {
        return {
          type: 'dom',
          critical: false,
          userMessage: '🖥️ Display issue detected. Some UI elements may not work.',
          action: 'none'
        };
      }

      // Default
      return {
        type: 'general',
        critical: false,
        userMessage: '⚠️ An error occurred. The game should continue working normally.',
        action: 'none'
      };
    }

    function showUserErrorNotification(message, action) {
      // Create a special error toast that's more prominent
      const errorToast = document.createElement('div');
      errorToast.className = 'error-toast';
      errorToast.innerHTML = `
    <div class="error-content">
      <div class="error-icon">⚠️</div>
      <div class="error-message">${message}</div>
      ${action === 'save' ? '<button class="error-action" onclick="showSaveOptions()">💾 Save Options</button>' : ''}
    </div>
  `;

      // Add styles if not already added
      if (!document.querySelector('#error-toast-styles')) {
        const style = document.createElement('style');
        style.id = 'error-toast-styles';
        style.textContent = `
      .error-toast {
        position: fixed;
        top: 20px;
        right: 20px;
        background: linear-gradient(135deg, #e74c3c, #c0392b);
        color: white;
        padding: 15px;
        border-radius: 12px;
        box-shadow: 0 4px 20px rgba(231, 76, 60, 0.3);
        z-index: 10000;
        max-width: 300px;
        animation: slideIn 0.3s ease-out;
      }
      .error-content {
        display: flex;
        flex-direction: column;
        gap: 10px;
      }
      .error-icon {
        font-size: 1.5rem;
        text-align: center;
      }
      .error-message {
        font-size: 0.9rem;
        line-height: 1.4;
      }
      .error-action {
        background: rgba(255, 255, 255, 0.2);
        border: 1px solid rgba(255, 255, 255, 0.3);
        color: white;
        padding: 8px 12px;
        border-radius: 6px;
        cursor: pointer;
        font-size: 0.8rem;
        transition: all 0.2s ease;
      }
      .error-action:hover {
        background: rgba(255, 255, 255, 0.3);
      }
      @keyframes slideIn {
        from { transform: translateX(100%); opacity: 0; }
        to { transform: translateX(0); opacity: 1; }
      }
    `;
        document.head.appendChild(style);
      }

      document.body.appendChild(errorToast);

      // Auto-remove after 8 seconds
      setTimeout(() => {
        if (errorToast.parentNode) {
          errorToast.parentNode.removeChild(errorToast);
        }
      }, 8000);

      // Remove on click
      errorToast.addEventListener('click', () => {
        if (errorToast.parentNode) {
          errorToast.parentNode.removeChild(errorToast);
        }
      });
    }

