    // Save operation mutex to prevent race conditions
    let saveMutex = false;
    let saveQueue = [];

    async function save() {
      // If save is already in progress, queue this request
      if (saveMutex) {
        return new Promise((resolve) => {
          saveQueue.push(resolve);
        });
      }

      // Acquire mutex
      saveMutex = true;

      try {
        // Validate game state before saving
        if (!validateSaveData(G)) {
          logError('Save Validation Failed', new Error('Invalid game state detected'));
          // Attempt to repair game state
          repairGameState();
        }

        const saveData = JSON.stringify(G);

        // Try localStorage first with quota handling
        if (tryLocalStorageSave(saveData)) {
          releaseSaveMutex();
          return true;
        }

        // Fallback to sessionStorage
        if (trySessionStorageSave(saveData)) {
          releaseSaveMutex();
          return true;
        }

        // Fallback to IndexedDB (async)
        const indexedDbSuccess = await tryIndexedDBSave(saveData);
        if (indexedDbSuccess) {
          releaseSaveMutex();
          return true;
        }

        // Final fallback to URL parameters for Google Sites
        logError('All Storage Methods Failed', new Error('Using URL fallback'));
        saveToURL();
        releaseSaveMutex();
        return false;

      } catch (e) {
        logError('Save Error', e);
        // Emergency fallback
        saveToURL();
        releaseSaveMutex();
        return false;
      }
    }

    function releaseSaveMutex() {
      saveMutex = false;

      // Process queued save requests
      if (saveQueue.length > 0) {
        const nextResolve = saveQueue.shift();
        nextResolve(save());
      }
    }

