    // Event listener management
    const eventListeners = new Map();

    function addManagedEventListener(element, event, handler, options = {}) {
      if (!element) return null;

      const key = `${element.id || 'anonymous'}-${event}`;

      // Remove existing listener if present
      if (eventListeners.has(key)) {
        const existingHandler = eventListeners.get(key);
        element.removeEventListener(event, existingHandler, options);
      }

      // Add new listener
      element.addEventListener(event, handler, options);
      eventListeners.set(key, handler);

      return handler;
    }

    function cleanupEventListeners() {
      eventListeners.forEach((handler, key) => {
        const [elementId, event] = key.split('-');
        const element = elementId === 'anonymous' ? document : document.getElementById(elementId);
        if (element) {
          element.removeEventListener(event, handler);
        }
      });
      eventListeners.clear();
    }

    // Safe DOM manipulation
    function safelyUpdateContainer(container, htmlStrings) {
      if (!container) return;

      const newContent = htmlStrings.join('');
      if (container.innerHTML !== newContent) {
        // Clear existing content
        while (container.firstChild) {
          container.removeChild(container.firstChild);
        }

        // Create temporary div to parse HTML
        const temp = document.createElement('div');
        temp.innerHTML = newContent;

        // Move nodes to actual container
        while (temp.firstChild) {
          container.appendChild(temp.firstChild);
        }
      }
    }
