    function buySkill(skillId) {
      // Find which tree contains this skill
      let treeKey = null;
      let skill = null;

      for (const key in SKILL_TREES) {
        const foundSkill = SKILL_TREES[key].skills.find(s => s.id === skillId);
        if (foundSkill) {
          treeKey = key;
          skill = foundSkill;
          break;
        }
      }

      if (!skill || !treeKey) return;

      const currentLevel = G.skillLevels[treeKey]?.[skillId] || 0;
      if (currentLevel >= skill.maxLevel) return toast('Skill already maxed!');

      if (G.skillPoints < skill.cost) return toast('Need more skill points!');

      // Deduct skill points and upgrade skill
      G.skillPoints -= skill.cost;
      if (!G.skillLevels[treeKey]) G.skillLevels[treeKey] = {};
      G.skillLevels[treeKey][skillId] = currentLevel + 1;

      toast(`${skill.name} upgraded to level ${currentLevel + 1}!`);
      renderSkills();
      ui();
      save();
    }

