      function openPacks(n) { if (G.cardRolling) return toast('Wait for the current card roll'); n = Math.max(1, Math.min(3, n)); let each = packPrice(), total = each * n; if (G.points < total) return toast('Need ' + fmt(total)); G.points -= total; let got = [], bag = weightedCardBag(); for (let i = 0; i < n * 3; i++) { let b = rollCardFromPool(), m = rollMutation(); got.push(cardKey(b.id, m && m.id)) } G.cardBuys = (G.cardBuys || 0) + n; G.cardRolling = true; let pr = document.getElementById('packResults'); pr.innerHTML = got.map((k, i) => `<div class="box"><div class="case-row-label">Card ${i + 1}</div><div class="case-window"><div class="strip" id="packStrip${i}" style="transition:none;transform:translateX(0)">${buildCardRollStrip(k, bag)}</div></div></div>`).join(''); setTimeout(() => got.forEach((_, i) => startRollStrip('packStrip' + i)), 60); setTimeout(() => { got.forEach(k => { let sp = splitCardKey(k); addCard(sp.id, 1, sp.mut) }); pr.innerHTML = '<div class="section" style="grid-column:1/-1;margin-top:0">Pack Results</div>' + got.map(k => cardTile(k)).join(''); G.cardRolling = false; toast('Opened ' + n + ' pack' + (n > 1 ? 's' : '') + '!'); renderCards(); ui(); save() }, 3500) }
